// Supabase manda { type, table, schema, record, old_record }. Seguimos nada más si es un
// INSERT en public.ideas con texto para clasificar. Cualquier otra cosa (por ejemplo un
// UPDATE, si alguien activó ese evento) recibe un 400 y no toca la base: así no hay bucles.
const evento = $input.first().json.body ?? {};
const fila = evento.record ?? {};

const motivos = [];
if (evento.type !== 'INSERT') motivos.push(`el evento es ${evento.type ?? 'desconocido'} y se espera INSERT`);
if (evento.table !== 'ideas' || evento.schema !== 'public') motivos.push(`la tabla es ${evento.schema}.${evento.table} y se espera public.ideas`);
if (fila.id === undefined || fila.id === null) motivos.push('la fila no trae id');
if (typeof fila.idea !== 'string' || !fila.idea.trim()) motivos.push('la fila no trae texto en «idea»');

return [{
  json: {
    valido: motivos.length === 0,
    motivos,
    id: fila.id ?? null,
    idea: typeof fila.idea === 'string' ? fila.idea.trim() : '',
  },
}];

// La IA puede contestar con mayúsculas, tildes o espacios. Normalizamos y, si no es una
// de la lista, usamos «otra»: así en la base quedan siempre los mismos valores.
const VALIDAS = ['ia', 'web3', 'automatizacion', 'impacto-social', 'educacion', 'otra'];
const evento = $('Leer el evento').first().json;
const salida = $input.first().json.output ?? {};

const limpia = String(salida.categoria ?? '')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .trim()
  .replace(/[\s_]+/g, '-');
const categoria = VALIDAS.includes(limpia) ? limpia : 'otra';

return [{ json: { id: evento.id, categoria, motivo: String(salida.motivo ?? '').trim() } }];
